1: //! Shipping quotes, one function per zone.
2: //!
3: //! Every zone prices the same way — a flat handling fee, then a per-kilo rate up
4: //! to the zone's break weight, then a heavier rate above it, then a surcharge if
5: //! the parcel is over the zone's oversize limit. Only the numbers differ, so the
6: //! five bodies are deliberately identical in shape: a reviewer comparing two
7: //! zones should be reading constants, not control flow.
8: 
9: /// A quote in pence.
10: pub type Pence = u64;
11: 
12: pub fn quote_zone_a(grams: u64, longest_cm: u64) -> Pence {
13:     let handling = 250;
14:     let break_grams = 2_000;
15:     let light_rate = 40;
16:     let heavy_rate = 65;
17:     let oversize_cm = 60;
18:     let oversize_fee = 500;
19: 
20:     let light = grams.min(break_grams);
21:     let heavy = grams.saturating_sub(break_grams);
22:     let mut total = handling;
23:     total += light * light_rate / 1_000;
24:     total += heavy * heavy_rate / 1_000;
25:     if longest_cm > oversize_cm {
26:         total += oversize_fee;
27:     }
28:     total
29: }
