1: // Contract test for the shipping quotes. FROZEN: a solver must not modify this
2: // file.
3: #[path = "lib.rs"]
4: mod lib;
5: 
6: use lib::*;
7: 
8: // --- the reported symptom ---
9: 
10: #[test]
11: fn a_parcel_exactly_at_the_zone_c_limit_is_not_oversize() {
12:     // The oversize limit is the largest size that still ships as a normal
13:     // parcel: a parcel AT the limit is inside it. Zone C charges the surcharge
14:     // anyway.
15:     let at_limit = quote_zone_c(1_000, 50);
16:     let under = quote_zone_c(1_000, 49);
17:     assert_eq!(
18:         at_limit, under,
19:         "a parcel at the zone C limit was surcharged: {at_limit} vs {under}"
20:     );
21: }
22: 
23: #[test]
24: fn a_parcel_over_the_zone_c_limit_is_still_oversize() {
25:     assert_eq!(quote_zone_c(1_000, 51) - quote_zone_c(1_000, 50), 900);
26: }
27: 
28: // --- the invariant across every zone ---
29: 
30: #[test]
31: fn every_zone_treats_its_limit_the_same_way() {
32:     // Same rule everywhere: at the limit is inside, one over is outside.
33:     let zones: [(fn(u64, u64) -> Pence, u64, u64); 5] = [
34:         (quote_zone_a, 60, 500),
35:         (quote_zone_b, 60, 750),
36:         (quote_zone_c, 50, 900),
37:         (quote_zone_d, 50, 1_200),
38:         (quote_zone_e, 40, 1_800),
39:     ];
40:     for (i, (q, limit, fee)) in zones.iter().enumerate() {
41:         assert_eq!(
42:             q(1_000, *limit),
43:             q(1_000, limit - 1),
44:             "zone {i} surcharges a parcel at its limit"
45:         );
46:         assert_eq!(
47:             q(1_000, limit + 1) - q(1_000, *limit),
48:             *fee,
49:             "zone {i} does not surcharge a parcel over its limit"
50:         );
51:     }
52: }
53: 
54: // --- everything that already worked must keep working ---
55: 
56: #[test]
57: fn the_zone_rates_are_unchanged() {
58:     // A 3kg parcel, well under every oversize limit.
59:     assert_eq!(quote_zone_a(3_000, 10), 250 + 80 + 65);
60:     assert_eq!(quote_zone_b(3_000, 10), 300 + 110 + 90);
61:     assert_eq!(quote_zone_c(3_000, 10), 400 + 105 + 180);
62:     assert_eq!(quote_zone_d(3_000, 10), 550 + 142 + 240);
63:     assert_eq!(quote_zone_e(3_000, 10), 800 + 130 + 440);
64: }
65: 
66: #[test]
67: fn a_zero_weight_parcel_pays_only_handling() {
68:     assert_eq!(quote_zone_a(0, 10), 250);
69:     assert_eq!(quote_zone_c(0, 10), 400);
70:     assert_eq!(quote_zone_e(0, 10), 800);
71: }

